DROP TABLE IF EXISTS `carlisting_listings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `carlisting_listings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int unsigned NOT NULL,
  `make_id` int unsigned NOT NULL,
  `model_id` int unsigned NOT NULL,
  `car_type` enum('new','used') DEFAULT NULL,
  `owner_show` enum('F','T') NOT NULL DEFAULT 'T',
  `feature_fuel_id` int unsigned DEFAULT NULL,
  `feature_gearbox_id` int unsigned DEFAULT NULL,
  `feature_doors_id` int unsigned DEFAULT NULL,
  `feature_class_id` int unsigned DEFAULT NULL,
  `feature_seats_id` int unsigned DEFAULT NULL,
  `feature_type_id` int unsigned DEFAULT NULL,
  `feature_colors_id` int unsigned DEFAULT NULL,
  `listing_refid` varchar(255) DEFAULT NULL,
  `listing_price` decimal(15,2) unsigned DEFAULT NULL,
  `listing_month` int DEFAULT NULL,
  `listing_year` year DEFAULT NULL,
  `listing_mileage` int unsigned DEFAULT NULL,
  `listing_power` int unsigned DEFAULT NULL,
  `views` int unsigned NOT NULL DEFAULT '0',
  `created` datetime NOT NULL,
  `modified` datetime DEFAULT NULL,
  `expire` date DEFAULT NULL,
  `last_extend` enum('free','paid') DEFAULT NULL,
  `is_featured` enum('F','T') NOT NULL DEFAULT 'F',
  `status` enum('T','F','E') NOT NULL DEFAULT 'F',
  PRIMARY KEY (`id`),
  KEY `make_id` (`make_id`),
  KEY `model_id` (`model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
